import collections
import hashlib
import json
import os
import re
import signal
import stat
import subprocess
import sys
import tempfile
import time

WORD = "HELLOWORLD"
REPETITIONS = 1000
TOTAL = REPETITIONS * len(WORD)
CALIBRATION_S = 3.0
STATE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "hello_world_24h.state.json")
LEDGER = os.path.join(tempfile.gettempdir(), "hello_world_24h_ledger.txt")
_T_START = time.perf_counter()


def _fail(message):
    sys.stderr.write("AUDIT FAILURE: " + message + "\n")
    sys.exit(1)


def _link(previous, rep, pos, letter):
    return hashlib.sha256(f"{previous}|{rep}|{pos}|{letter}".encode()).hexdigest()


def read_arguments():
    args = sys.argv[1:]
    reset = "reset" in args
    if reset:
        args.remove("reset")
    try:
        hours = float(args[0]) if args else 24.0
        if hours <= 0:
            raise ValueError
    except ValueError:
        sys.stderr.write("Usage: python hello_world_24h_en.py [hours] [reset]\n")
        sys.exit(2)
    return hours, bool(args), reset


def _date(seconds_from_now):
    return time.strftime("%Y-%m-%d %H:%M", time.localtime(time.time() + seconds_from_now))

def work(d, n):
    sha = hashlib.sha256
    for _ in range(n):
        d = sha(d).digest()
    return d

def calibrate():
    d = hashlib.sha256(b"calibration").digest()
    n, t0 = 0, time.perf_counter()
    while time.perf_counter() - t0 < CALIBRATION_S:
        d = work(d, 100_000)
        n += 100_000
    return n / (time.perf_counter() - t0)


def load_state():
    try:
        with open(STATE, encoding="utf-8") as f:
            s = json.load(f)
        if s["total"] != TOTAL or not 0 <= s["done"] < TOTAL or s["steps_per_letter"] < 1:
            return None
        bytes.fromhex(s["digest"])
        float(s["hours"])
        return s
    except (OSError, ValueError, KeyError, TypeError):
        return None


def save_state(s):
    tmp = STATE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(s, f)
    os.replace(tmp, STATE)


def layer1_source_code():
    try:
        with open(__file__, encoding="utf-8") as f:
            source = f.read()
    except (OSError, NameError):
        sys.stderr.write("(warning) could not read my own source, skipping layer 1\n")
        return False
    calls = len(re.findall(r"^slow_letter\(", source, re.M))
    closes = len(re.findall(r"^close_repetition\(", source, re.M))
    numbers = [int(n) for n in re.findall(r"^# === Repetition (\d{4})/1000 ===$", source, re.M)]
    if calls != TOTAL:
        _fail(f"the code has {calls} explicit prints and should have {TOTAL}")
    if closes != REPETITIONS:
        _fail(f"the code has {closes} closes and should have {REPETITIONS}")
    if numbers != list(range(1, REPETITIONS + 1)):
        _fail("the blocks are not 1..1000 in order (one is missing or extra)")
    return True


class Witness:

    def __init__(self, real):
        self.real = real
        self.chunks = []
        self.tail = ""
        self.lines = 0

    def write(self, s):
        n = self.real.write(s)
        self.chunks.append(s)
        self.tail = (self.tail + s)[-64:]
        self.lines += s.count("\n")
        return n

    def flush(self):
        self.real.flush()

    def text(self):
        return "".join(self.chunks)

    def __getattr__(self, name):
        return getattr(self.real, name)


def _interrupted(signum, frame):
    sys.stderr.write("\nInterrupted. Progress is saved: run it again to continue.\n")
    sys.exit(130)


HOURS, HOURS_GIVEN, RESET = read_arguments()
LAYER1_OK = layer1_source_code()
signal.signal(signal.SIGINT, _interrupted)

if RESET and os.path.exists(STATE):
    os.remove(STATE)
_state = load_state()
if _state is None:
    _rate = calibrate()
    _state = {
        "total": TOTAL,
        "hours": HOURS,
        "steps_per_letter": max(1, int(_rate * HOURS * 3600 / TOTAL)),
        "done": 0,
        "digest": hashlib.sha256(b"HELLOWORLD-24h").hexdigest(),
    }
    sys.stderr.write(f"CPU: {_rate / 1e6:.2f} M steps/s -> {_state['steps_per_letter']:,} steps per letter\n")
    sys.stderr.write(f"Target ~{HOURS:g} h. Finishes around {_date(HOURS * 3600)}\n")
else:
    _remaining_s = (TOTAL - _state["done"]) * _state["hours"] * 3600 / TOTAL
    sys.stderr.write(f"Resuming: {_state['done']} letters already earned (shown instantly)\n")
    sys.stderr.write(f"~{_remaining_s / 3600:.2f} h left. Finishes around {_date(_remaining_s)}\n")
    if HOURS_GIVEN and HOURS != _state["hours"]:
        sys.stderr.write(f"(warning) keeping the saved target of {_state['hours']:g} h; "
                         "use 'reset' to change it\n")

_START = _state["done"]
_session = {"t0": None}
_witness = Witness(sys.stdout)
sys.stdout = _witness
_ledger = {"hash": "0" * 64}
_block = []
with open(LEDGER, "w", encoding="utf-8") as _f:
    _f.write("")


def slow_letter(rep, pos, letter):
    k = (rep - 1) * len(WORD) + pos
    if WORD[pos] != letter:
        _fail(f"rep {rep}, pos {pos}: asked for '{letter}' but the word says '{WORD[pos]}'")
    new = k >= _START
    if new:
        if k != _state["done"]:
            _fail(f"letter {k}: the saved progress says {_state['done']}")
        if _session["t0"] is None:
            _session["t0"] = time.perf_counter()
        seed = hashlib.sha256(
            bytes.fromhex(_state["digest"]) + letter.encode() + k.to_bytes(4, "big")).digest()
        d = work(seed, _state["steps_per_letter"])
        _state["done"], _state["digest"] = k + 1, d.hex()
        save_state(_state)
    print(letter, flush=new)
    if _witness.tail[-2:] != letter + "\n":
        _fail(f"rep {rep}, pos {pos}: '{letter}' did not show up on stdout")
    if _witness.lines != k + 1:
        _fail(f"rep {rep}, pos {pos}: {_witness.lines} lines so far, should be {k + 1} "
              "(something earlier was lost)")
    _ledger["hash"] = _link(_ledger["hash"], rep, pos, letter)
    _block.append(letter)
    if new and (k + 1) % 100 == 0:
        pace = (time.perf_counter() - _session["t0"]) / (k + 1 - _START)
        left = (TOTAL - k - 1) * pace / 3600
        sys.stderr.write(f"[{k + 1}/{TOTAL}] {100 * (k + 1) / TOTAL:.1f}%  ~{left:.2f} h left\n")


def close_repetition(rep):
    if "".join(_block) != WORD:
        _fail(f"rep {rep}: the block came out as {''.join(_block)!r}")
    expected = "".join(c + "\n" for c in WORD)
    if _witness.tail[-len(expected):] != expected:
        _fail(f"rep {rep}: the last 10 lines of stdout are not HELLOWORLD")
    if _state["done"] < rep * len(WORD):
        _fail(f"rep {rep}: saved progress ({_state['done']}) is behind what was printed")
    _block.clear()
    with open(LEDGER, "a", encoding="utf-8") as f:
        f.write(f"{rep} {_ledger['hash']}\n")


def final_audit(layer1_ok):
    sys.stdout.flush()
    output = _witness.text()
    sys.stdout = _witness.real

    h = "0" * 64
    expected = []
    for rep in range(1, REPETITIONS + 1):
        for pos, letter in enumerate(WORD):
            h = _link(h, rep, pos, letter)
        expected.append(f"{rep} {h}")
    with open(LEDGER, encoding="utf-8") as f:
        on_disk = f.read().splitlines()
    if on_disk != expected:
        _fail("the ledger on disk does not match the recomputed chain")

    lines = output.split("\n")
    if lines[-1] != "":
        _fail("the output does not end with a newline")
    lines = lines[:-1]
    if len(lines) != TOTAL:
        _fail(f"{len(lines)} lines came out and there should be {TOTAL}")
    if "".join(lines) != WORD * REPETITIONS:
        _fail("the letters do not form HELLOWORLD x 1000")
    census = collections.Counter(lines)
    for letter, n in collections.Counter(WORD).items():
        if census[letter] != n * REPETITIONS:
            _fail(f"census: '{letter}' appears {census[letter]} times and should be {n * REPETITIONS}")

    child = subprocess.run(
        [sys.executable, "-c", f"print('\\n'.join({WORD!r}))"],
        capture_output=True, text=True, check=True,
    )
    if child.stdout * REPETITIONS != output:
        _fail("the external process prints something different from what I printed")

    layer7 = "skipped (stdout is not a file)"
    try:
        sys.stdout.flush()
        info = os.fstat(1)
        if stat.S_ISREG(info.st_mode):
            expected_bytes = len(output.encode()) + (output.count("\n") if os.linesep == "\r\n" else 0)
            layer7 = "OK" if info.st_size == expected_bytes else (
                f"WARNING: the file is {info.st_size} bytes and I expected {expected_bytes} "
                "(normal if you used '>>')")
    except OSError:
        pass

    certificate = _state["digest"]
    for path in (LEDGER, STATE):
        try:
            os.remove(path)
        except OSError:
            pass

    e = sys.stderr.write
    e("\n=== AUDIT COMPLETE ===\n")
    e(f"0. work (SHA-256) ....... OK ({_state['steps_per_letter']:,} steps x {TOTAL} letters)\n")
    e(f"   certificate .......... {certificate}\n")
    e(f"1. source code .......... {'OK' if layer1_ok else 'skipped'} ({TOTAL} prints, {REPETITIONS} blocks)\n")
    e(f"2. per-letter witness ... OK ({TOTAL} letters, each with everything before it intact)\n")
    e(f"3. block close .......... OK ({REPETITIONS} x {WORD})\n")
    e(f"4. ledger + hash ........ OK (final chain {h[:16]}...)\n")
    e(f"5. letter census ........ OK ({dict(census)})\n")
    e("6. external process .... OK\n")
    e(f"7. operating system ..... {layer7}\n")
    e(f"This session took {(time.perf_counter() - _T_START) / 3600:.3f} h\n")


